/* Minimalist abstract Variant Alpha CSS Background System */
.bg-layer-1-1 {
  position: fixed;
  inset: 0;
  z-index: -1;
  background-color: var(--bg-surface, #090a0f);
  background-image: 
    radial-gradient(at 20% 15%, rgba(99, 102, 241, 0.12) 0px, transparent 60%),
    radial-gradient(at 75% 65%, rgba(6, 182, 212, 0.09) 0px, transparent 55%),
    linear-gradient(to bottom, rgba(9, 10, 15, 0.8), rgba(9, 10, 15, 0.98));
  background-attachment: fixed;
  pointer-events: none;
}

/* Noise grain overlay */
.bg-layer-1-1::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)' opacity='0.035'/%3E%3C/svg%3E");
  opacity: 0.4;
  mix-blend-mode: overlay;
  pointer-events: none;
}

@media (prefers-reduced-motion: reduce) {
  .bg-layer-1-1 {
    background-attachment: scroll;
    animation: none !important;
  }
}

