// Interactive spotlight Variant Alpha Interactive Canvas Background (TypeScript / Vanilla JS)
export class BackgroundRunner_36_1 {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private mouse = { x: 0, y: 0, targetX: 0, targetY: 0 };
  private animId: number = 0;

  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d')!;
    this.resize();
    window.addEventListener('resize', () => this.resize());
    window.addEventListener('mousemove', (e) => this.onMove(e));
    this.animate();
  }

  private resize(): void {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.canvas.width = window.innerWidth * dpr;
    this.canvas.height = window.innerHeight * dpr;
    this.ctx.scale(dpr, dpr);
  }

  private onMove(e: MouseEvent): void {
    this.mouse.targetX = e.clientX;
    this.mouse.targetY = e.clientY;
  }

  private animate = (): void => {
    this.mouse.x += (this.mouse.targetX - this.mouse.x) * 0.08;
    this.mouse.y += (this.mouse.targetY - this.mouse.y) * 0.08;

    this.ctx.fillStyle = 'rgba(9, 10, 15, 0.2)';
    this.ctx.fillRect(0, 0, window.innerWidth, window.innerHeight);

    // Dynamic accent glow
    const grad = this.ctx.createRadialGradient(
      this.mouse.x, this.mouse.y, 10,
      this.mouse.x, this.mouse.y, 350
    );
    grad.addColorStop(0, 'rgba(99, 102, 241, 0.18)');
    grad.addColorStop(1, 'rgba(99, 102, 241, 0)');
    this.ctx.fillStyle = grad;
    this.ctx.fillRect(0, 0, window.innerWidth, window.innerHeight);

    if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      this.animId = requestAnimationFrame(this.animate);
    }
  };

  public destroy(): void {
    cancelAnimationFrame(this.animId);
  }
}

